  if (view && view.id !== MC_VIEW) { if (nl(view.id)) lose(view.id, "the view's id, which has a line break"); else out.push(`%% id: ${view.id}`); }
  out.push('classDiagram', view && view.direction === 'down' ? '  direction TB' : '  direction LR');

