const circleIn = (n, s, t) => { const r = n.w / 2, u = t - (s === 'L' || s === 'R' ? n.y + n.h / 2 : n.x + n.w / 2); return r * (1 - Math.sqrt(Math.max(0, 1 - (u / r) ** 2))); };
