  const w = Math.min(UC.max, Math.max(...st.map(t => textW(t, UC.st)), ...name.map(l => textW(l, UC.px)), ...(eps.length ? [textW('extension points', UC.st), ...eps.map(p => textW(p, UC.ep))] : [])));
