const snDocIcon = (x, y) => `<path d="M${r2(x)} ${r2(y)}H${r2(x + 8)}L${r2(x + 12)} ${r2(y + 4)}V${r2(y + 14)}H${r2(x)}Z M${r2(x + 8)} ${r2(y)}V${r2(y + 4)}H${r2(x + 12)}" class="n-det sn-icon" fill="${SN.bg}" stroke="${SN.line}"/>`;
