    const lo = a.c.at <= b.c.at ? a : b, hi = lo === a ? b : a, L = a.L.j >= b.L.j ? a.L : b.L, w = trNum(c.w), h = trNum(c.h);
    const xa = xOf(lo.c.at), xb = xOf(hi.c.at), cx = (xa + xb) / 2;
