  layout: { run: tmRun, pins: false },
  draw: tmDraw,
  validate: tmProblems,
  rules: TM_RULES,
  describe: tmDescribe,
  rows: tmRows,
  edits: { connect: tmConnect, moveTo: tmMoveTo, add: tmAdd, remove: tmRemove, rename: tmRename, key: tmKeyHook },
