/* ---------- the flowchart, flowchart (work package M2.3, notes/milestone-2.md §7.2) ----------
   Ten symbols: the decision is stage 4's diamond and the connector a circle over SHAPE.initial's outline, both read only;
   the database is drawn over the map's cylinder's outline with a lid line of its own (the cylinder's det is tinted by a map
   kind); the other seven are this file's, each with size, out, inset (a line's end slid onto it, stage 4 §4.2), face, ports
   and draw. A node's text is flowWrap's, three lines of 180 px, then cut, inside the shape's text box (its padding per
   side, FC_SHAPES). Flows are solid with a filled arrow, their labels cut at 280 px. Laid out down unless the view says
   right (model.md row 21), gap 48 with gapAfter's widening, labelGaps, repair and reroute off (§11). Ships in
   lib/umlimator-all.js only. */

const FC_OBJ = x => x !== null && typeof x === 'object' && !Array.isArray(x), FC_ARR = x => (Array.isArray(x) ? x : []);
const FC_TXT = x => (x != null && String(x).trim() !== '' ? String(x).trim() : '');
const FC = { px: 12, lh: 16, max: 180, padX: 12, padY: 8, minW: 96, minH: 40, slant: 14, wave: 5, slope: 12, side: 8, line: 'var(--um-muted)', ink: 'var(--um-text)', bg: 'var(--um-stage-bg)' };
// each node type: its shape and its word (accessible names, the PDF, the legend)
const FC_LOOK = {
  'flow.Terminator': ['terminator', 'Terminator'], 'flow.Process': ['process', 'Process'], 'flow.Decision': ['diamond', 'Decision'],
  'flow.InputOutput': ['io', 'Input/output'], 'flow.PredefinedProcess': ['predefined', 'Predefined process'], 'flow.Document': ['doc', 'Document'],
  'flow.Database': ['database', 'Database'], 'flow.ManualInput': ['manual', 'Manual input'], 'flow.Delay': ['delay', 'Delay'],
  'flow.Connector': ['connector', 'Connector'], 'uml.Comment': ['note', 'Comment'],
};
const FC_NODES = Object.keys(FC_LOOK).filter(t => t !== 'uml.Comment'); // what a flow may end on
const fcLook = x => (Object.hasOwn(FC_LOOK, x.type) ? FC_LOOK[x.type] : ['process', String(x.type || 'Node').split('.').pop()]);

/* ---- the shapes ---- */
const arcIn = (r, u) => r - Math.sqrt(Math.max(0, r * r - Math.min(r, Math.abs(u)) ** 2)); // a circle's depth at u from its axis
const grow = (n, d) => ({ x: n.x - d, y: n.y - d, w: n.w + 2 * d, h: n.h + 2 * d });
const WAVE = FC.wave / 0.2887; // a cubic's control offset that swings its curve by FC.wave each way
// the document's wavy bottom at u (0 at its right, 1 at its left): how far above the box's bottom it is
const waveIn = u => FC.wave - 3 * WAVE * u * (1 - u) * (2 * u - 1);
// [text padding left, right, top, bottom] past FC.padX and FC.padY, out(n, d), inset(n, side, t), det(n): a shape's own
const FC_SHAPES = {
  process: [() => [0, 0, 0, 0], boxOut(0), () => 0],
  terminator: [h => [h / 4, h / 4, 0, 0], (n, d = 0) => boxOut(n.h / 2)(n, d),
    (n, s, t) => { const r = n.h / 2; return s === 'L' || s === 'R' ? arcIn(r, t - n.y - r) : t < n.x + r ? arcIn(r, n.x + r - t) : t > n.x + n.w - r ? arcIn(r, t - n.x - n.w + r) : 0; }],
  io: [() => [FC.slant, FC.slant, 0, 0], (n, d = 0) => { const { x, y, w, h } = grow(n, d), k = FC.slant; return `M${r2(x + k)} ${r2(y)}H${r2(x + w)}L${r2(x + w - k)} ${r2(y + h)}H${r2(x)}Z`; },
    (n, s, t) => { const k = FC.slant, v = Math.min(1, Math.max(0, (t - n.y) / n.h)), u = Math.max(0, Math.min(1, (n.x + k - t) / k)), b = Math.max(0, Math.min(1, (t - n.x - n.w + k) / k));
      return s === 'L' ? k * (1 - v) : s === 'R' ? k * v : s === 'T' ? n.h * u : n.h * b; }],
  predefined: [() => [FC.side, FC.side, 0, 0], boxOut(0), () => 0,
    n => `<path d="M${r2(n.x + FC.side)} ${r2(n.y)}V${r2(n.y + n.h)}M${r2(n.x + n.w - FC.side)} ${r2(n.y)}V${r2(n.y + n.h)}" class="n-det" stroke="${FC.line}"/>`],
  doc: [() => [0, 0, 0, 2 * FC.wave], (n, d = 0) => { const { x, y, w, h } = grow(n, d), b = y + h - FC.wave;
    return `M${r2(x)} ${r2(y)}H${r2(x + w)}V${r2(b)}C${r2(x + 2 * w / 3)} ${r2(b - WAVE)} ${r2(x + w / 3)} ${r2(b + WAVE)} ${r2(x)} ${r2(b)}Z`; },
  (n, s, t) => (s === 'B' ? waveIn(Math.max(0, Math.min(1, (n.x + n.w - t) / n.w))) : 0), null, n => [n.y, n.y + n.h - FC.wave]],
  // the map's cylinder's outline; its lid's front edge drawn here, in the typed line colour
  database: [() => [0, 0, 12, 6], (n, d = 0) => SHAPE.cylinder.out(n, d), (n, s, t) => SHAPE.cylinder.inset(n, s, t),
    n => { const ry = SHAPE.cylinder.ry(n); return `<path d="M${r2(n.x)} ${r2(n.y + ry)}A${r2(n.w / 2)} ${ry} 0 0 0 ${r2(n.x + n.w)} ${r2(n.y + ry)}" class="n-det" fill="none" stroke="${FC.line}"/>`; },
    n => SHAPE.cylinder.face(n)],
  manual: [() => [0, 0, FC.slope, 0], (n, d = 0) => { const { x, y, w, h } = grow(n, d); return `M${r2(x)} ${r2(y + FC.slope)}L${r2(x + w)} ${r2(y)}V${r2(y + h)}H${r2(x)}Z`; },
    (n, s, t) => (s === 'T' ? FC.slope * Math.max(0, Math.min(1, 1 - (t - n.x) / n.w)) : s === 'L' && t < n.y + FC.slope ? n.w * (n.y + FC.slope - t) / FC.slope : 0), null, n => [n.y + FC.slope, n.y + n.h]],
  delay: [h => [0, h / 2, 0, 0], (n, d = 0) => { const { x, y, w, h } = grow(n, d), r = h / 2; return `M${r2(x)} ${r2(y)}H${r2(x + w - r)}A${r2(r)} ${r2(r)} 0 0 1 ${r2(x + w - r)} ${r2(y + h)}H${r2(x)}Z`; },
    (n, s, t) => { const r = n.h / 2; return s === 'R' ? arcIn(r, t - n.y - r) : (s === 'T' || s === 'B') && t > n.x + n.w - r ? arcIn(r, t - n.x - n.w + r) : 0; }],
};
const fcG = (n, shape, said, inner) => `<g class="node ${shape}" data-id="${esc(n.id)}" data-shape="${shape}" tabindex="-1" role="img" aria-label="${esc(n.aria || said)}">${inner}</g>`;
const fcBody = d => `<path d="${d}" class="n-mask"/><path d="${d}" class="n-body" fill="${FC.bg}" stroke="${FC.line}"/>`;
const fcText = (cx, y, t) => `<text x="${r2(cx)}" y="${r2(y)}" text-anchor="middle" class="c-name" fill="${FC.ink}" style="font:600 ${FC.px}px var(--um-sans)">${esc(t)}</text>`;
const fcSaid = (n, word) => (FC_TXT(n.label) ? `${word} ${FC_TXT(n.label)}` : word);
for (const [shape, [pad, out, inset, det, face]] of Object.entries(FC_SHAPES)) {
  const word = Object.values(FC_LOOK).find(l => l[0] === shape)[1];
  const S = SHAPE[shape] = { out, inset, face: face || (n => [n.y, n.y + n.h]),
    size(n) { const ls = flowWrap(n.label, FC.px, FC.max, 3), h = Math.max(FC.minH, 2 * FC.padY + Math.max(1, ls.length) * FC.lh), [l, r, t, b] = pad(h);
      return { w: Math.ceil(Math.max(FC.minW, ...ls.map(x => textW(x, FC.px) + 2 * FC.padX)) + l + r), h: Math.ceil(h + t + b) }; },
    draw(n) { const [l, r, t, b] = pad(n.h), w = n.w - l - r - 2 * FC.padX, ls = flowWrap(n.label, FC.px, FC.max, 3);
      const y0 = n.y + t + (n.h - t - b - ls.length * FC.lh) / 2, cx = n.x + l + (n.w - l - r) / 2;
      return fcG(n, shape, fcSaid(n, word), fcBody(out(n)) + (det ? det(n) : '') + ls.map((x, i) => fcText(cx, y0 + i * FC.lh + 12, fit(x, FC.px, w))).join('')); } };
  S.ports = (n, side, k = 1) => portsOn(S, n, side, k);
}
// the connector: a circle 28 px across, or as wide as its label (one or two characters) up to 40 px, a longer label cut
SHAPE.connector = { out: SHAPE.initial.out, inset: SHAPE.initial.inset, face: n => [n.y, n.y + n.h],
  size: n => { const d = Math.min(40, Math.max(28, Math.ceil(textW(FC_TXT(n.label), FC.px) + 10))); return { w: d, h: d }; },
  draw: n => fcG(n, 'connector', fcSaid(n, 'Connector'), fcBody(SHAPE.initial.out(n)) + (FC_TXT(n.label) ? fcText(n.x + n.w / 2, n.y + n.h / 2 + 4, fit(FC_TXT(n.label), FC.px, n.w - 6)) : '')) };
SHAPE.connector.ports = (n, side, k = 1) => portsOn(SHAPE.connector, n, side, k);

/* ---- the view read: its nodes, its lines, its flows in and out of each node, its starts and ends, its reading order ---- */
function fcIndex(model, view) {
  const N = new Map(), E = new Map(), path = new Map();
  FC_ARR(model && model.nodes).forEach((n, k) => { if (FC_OBJ(n) && typeof n.id === 'string' && !N.has(n.id)) { N.set(n.id, n); path.set(n.id, `nodes[${k}]`); } });
  FC_ARR(model && model.edges).forEach((e, k) => { if (FC_OBJ(e) && typeof e.id === 'string' && !E.has(e.id)) { E.set(e.id, e); path.set(e.id, `edges[${k}]`); } });
  const ids = view ? [...new Set(FC_ARR(view.nodeIds).filter(id => N.has(id)))] : [...N.keys()].filter(id => Object.hasOwn(FC_LOOK, N.get(id).type)), on = new Set(ids);
  const list = view && Array.isArray(view.edges) ? view.edges.map(x => (typeof x === 'string' ? E.get(x) : x)) : [...E.values()].filter(e => e.type === 'flow.Flow' || e.type === 'uml.CommentLink');
  const lines = list.filter(e => FC_OBJ(e) && typeof e.id === 'string' && on.has(e.from) && on.has(e.to)), flows = lines.filter(e => e.type === 'flow.Flow');
  const ins = id => flows.filter(e => e.to === id), outs = id => flows.filter(e => e.from === id);
  const term = id => N.get(id).type === 'flow.Terminator', starts = ids.filter(id => term(id) && !ins(id).length), ends = ids.filter(id => term(id) && !outs(id).length);
  // reading order: from each start along its flows, depth first, a decision's exits in the model's order (one branch read to its end before the next)
  const walk = [], seen = new Set(), visit = s => { const q = [s]; while (q.length) { const id = q.pop(); if (seen.has(id)) continue; seen.add(id); walk.push(id); outs(id).reverse().forEach(e => q.push(e.to)); } };
  starts.forEach(visit); const reached = new Set(seen); ids.forEach(visit);
  return { N, E, path, ids, lines, flows, ins, outs, starts, ends, walk, reached };
}
const fcName = x => String(x.label ?? x.id);
const fcCalled = x => (x ? (FC_TXT(x.label) || fcLook(x)[1].toLowerCase()) : '?');
const fcPlural = (k, w) => `${k} ${k === 1 ? w : w + 's'}`;

// accessible names (A1): "Decision Fit for resale?, exits yes to Refund the payment, no to Rejection letter"; "Terminator Return closed, an end"
function fcNodeName(I, x) {
  if (x.type === 'uml.Comment') return 'Comment: ' + fcName(x);
  const [, word] = fcLook(x), head = FC_TXT(x.label) ? `${word} ${FC_TXT(x.label)}` : word, o = I.outs(x.id);
  if (x.type === 'flow.Decision') return `${head}, ${o.length ? 'exits ' + o.map(e => `${FC_TXT(e.label) ? FC_TXT(e.label) + ' ' : ''}to ${fcCalled(I.N.get(e.to))}`).join(', ') : 'no exits'}`;
  if (x.type === 'flow.Terminator') return `${head}, ${I.starts.includes(x.id) ? 'a start' : I.ends.includes(x.id) ? 'an end' : 'flows in and out'}`;
  return head;
}
function fcLineName(I, e) {
  const t = FC_TXT(e.label), ends = `from ${fcCalled(I.N.get(e.from))} to ${fcCalled(I.N.get(e.to))}`;
  return e.type === 'uml.CommentLink' ? `Comment link ${ends}` : `Flow ${ends}${t ? ': ' + t : ''}`;
}

/* ---- the legend: each line kind and each symbol the view draws (1.9's legendItem form) ---- */
const fcKey = (svg, name, says) => `<span class="lgi" title="${esc(name + ' — ' + says)}"><svg class="lgs" viewBox="0 0 28 16" aria-hidden="true"><g stroke="var(--um-muted)" stroke-width="1.4" stroke-linejoin="round" fill="none">${svg}</g></svg><b>${esc(name)}</b><span>${esc(says)}</span></span>`;
const FC_KEYS = [
  ['flow.Flow', '<path d="M2 8H18"/><path d="M17 4L26 8L17 12Z" fill="var(--um-muted)"/>', 'Flow', 'the next step'],
  ['uml.CommentLink', '<path d="M2 8H26" stroke-dasharray="3 2"/>', 'Comment link', 'what a comment is about'],
  ['flow.Terminator', '<rect x="3" y="3" width="22" height="10" rx="5"/>', 'Terminator', 'a start or an end'],
  ['flow.Process', '<rect x="3" y="3" width="22" height="10"/>', 'Process', 'a step'],
  ['flow.Decision', '<path d="M14 2L24 8L14 14L4 8Z"/>', 'Decision', 'a question, an exit per answer'],
  ['flow.InputOutput', '<path d="M7 3H25L21 13H3Z"/>', 'Input/output', 'data read or written'],
  ['flow.PredefinedProcess', '<rect x="3" y="3" width="22" height="10"/><path d="M6 3V13M22 3V13"/>', 'Predefined process', 'steps written out elsewhere'],
  ['flow.Document', '<path d="M3 3H25V11C19 7 9 16 3 11Z"/>', 'Document', 'a document made or read'],
  ['flow.Database', '<path d="M6 4V12A8 2 0 0 0 22 12V4"/><ellipse cx="14" cy="4" rx="8" ry="2"/>', 'Database', 'stored data'],
  ['flow.ManualInput', '<path d="M3 7L25 3V13H3Z"/>', 'Manual input', 'data keyed in by hand'],
  ['flow.Delay', '<path d="M4 3H18A5 5 0 0 1 18 13H4Z"/>', 'Delay', 'a wait'],
  ['flow.Connector', '<circle cx="14" cy="8" r="5"/>', 'Connector', 'flows joined, or carried on elsewhere'],
  ['uml.Comment', '<path d="M4 3H20L24 7V13H4Z"/>', 'Comment', 'a note on the chart'],
];

/* ---- the view laid out: { model, view, pos, memo } ---- */
function fcGeo({ model, view, pos, memo }) {
  const I = fcIndex(model, view), down = view.direction == null || view.direction === 'down', at = id => (FC_OBJ(pos) && Array.isArray(pos[id]) ? pos[id] : [0, 0]);
  const nodes = I.ids.map(id => { const x = I.N.get(id), [shape] = fcLook(x), d = { id, label: fcName(x), type: x.type, kind: 'file', shape, aria: fcNodeName(I, x), col: at(id)[0], row: at(id)[1] };
    return { ...d, ...SHAPE[shape].size(d) }; });
  const edges = I.lines.map(e => { const note = e.type === 'uml.CommentLink', label = note ? '' : FC_TXT(e.label);
    return { id: e.id, _id: e.id, type: e.type, from: e.from, to: e.to, ...(label ? { label, cut: 280 } : {}), end: note ? { from: 'none', to: 'none', dashed: true } : { from: 'none', to: 'arrow' },
      aria: fcLineName(I, e), ...(FC_OBJ(e.style) || typeof e.style === 'string' ? { style: e.style } : {}) }; });
  const g = layoutTyped({ nodes, edges, direction: down ? 'down' : 'right', gap: 48, rgap: 56, labelGaps: true, repair: false, reroute: false }, memo);
  const types = new Set([...I.lines.map(e => e.type), ...I.ids.map(id => I.N.get(id).type)]);
  // a new object: what layoutTyped returned is never edited (stage 4 §2.4). The slots: one per node, so L and the palette hear the selection
  return { ...g, order: [...I.walk, ...I.lines.map(e => e.id)], slots: g.nodes.map(n => ({ after: n.id, x: n.x + n.w / 2, y: n.y + n.h / 2 })),
    legend: FC_KEYS.filter(([t]) => types.has(t)).map(([, svg, name, says]) => fcKey(svg, name, says)) };
}

/* ---- validators (§7.2). Each problem: { level, rule, path, message, ids } ---- */
const FC_RULES = {
  'flow-ends': 'a flow joins two flowchart nodes',
  'start-end': 'a view has exactly one start (a terminator with no flow in) and at least one end (a terminator with no flow out)',
  'terminator-flows': 'a start has one flow out; an end has none out',
  'decision-exits': 'a decision has two or more flows out, each labelled, no two with one label',
  reachable: 'every node is reached from a start',
};
function fcProblems(model, view) {
  const I = fcIndex(model, view), out = [], q = id => { const x = I.N.get(id); return x && FC_TXT(x.label) ? `${id} ("${FC_TXT(x.label)}")` : id; };
  const say = (rule, path, ids, msg, level = 'warning') => out.push({ level, rule, path, ids, message: `${rule}: ${msg}` });
  const shown = new Set(I.ids), mine = id => I.N.has(id) && FC_NODES.includes(I.N.get(id).type), list = es => es.map(e => e.id).join(', ');
  I.E.forEach((e, id) => { if (e.type !== 'flow.Flow' || !(shown.has(e.from) || shown.has(e.to))) return;
    [e.from, e.to].forEach(end => { if (I.N.has(end) && !mine(end)) say('flow-ends', I.path.get(id), [id, end], `flow ${id} ends on ${q(end)}, a ${String(I.N.get(end).type).split('.').pop()}: a flow joins two flowchart nodes`, 'error'); }); });
  if (!view) return out;
  const vp = `views[${FC_ARR(model.views).indexOf(view)}]`;
  if (I.starts.length !== 1) say('start-end', vp, [view.id, ...I.starts], `view ${view.id} has ${fcPlural(I.starts.length, 'start')}${I.starts.length ? ` (${I.starts.map(q).join(', ')})` : ''}; it wants one`);
  if (!I.ends.length) say('start-end', vp, [view.id], `view ${view.id} has no end: no terminator without a flow out`);
  I.ids.forEach(id => { const x = I.N.get(id), i = I.ins(id), o = I.outs(id), p = I.path.get(id);
    if (x.type === 'flow.Terminator' && !i.length && o.length !== 1) say('terminator-flows', p, [id, ...o.map(e => e.id)], `the start ${q(id)} has ${o.length ? `${o.length} flows out (${list(o)})` : 'no flow out'}; it wants one`);
    if (x.type === 'flow.Terminator' && i.length && o.length) say('terminator-flows', p, [id, ...o.map(e => e.id)], `the end ${q(id)} has flows out (${list(o)}); a terminator with flows in is an end`);
    if (x.type === 'flow.Decision') { const bare = o.filter(e => !FC_TXT(e.label)), by = new Map(); o.forEach(e => { const k = FC_TXT(e.label).toLowerCase(); if (k) by.set(k, [...(by.get(k) || []), e]); }); // as connect reads them
      const twice = [...by.values()].filter(es => es.length > 1).flat();
      if (o.length < 2) say('decision-exits', p, [id, ...o.map(e => e.id)], `${q(id)} has ${fcPlural(o.length, 'exit')}; a decision wants two or more`);
      if (bare.length) say('decision-exits', p, [id, ...bare.map(e => e.id)], `${fcPlural(bare.length, 'exit')} of ${q(id)} ${bare.length === 1 ? 'has' : 'have'} no label (${list(bare)})`);
      if (twice.length) say('decision-exits', p, [id, ...twice.map(e => e.id)], `exits of ${q(id)} share a label (${list(twice)})`); }
    if (I.starts.length && mine(id) && !I.reached.has(id)) say('reachable', p, [id], `${q(id)} is reached from no start`); });
  return out;
}

/* ---- describe(): the view in sentences: each node in reading order (from the start, along its flows), then each line ---- */
function fcDescribe(model, viewId) {
  const v = FC_ARR(model && model.views).find(x => FC_OBJ(x) && x.id === viewId); if (!v) throw new Error(`umlimator: no view ${JSON.stringify(viewId)}`);
  const I = fcIndex(model, v);
  return [`${v.title || v.id}: a flowchart of ${fcPlural(I.ids.length, 'node')} and ${fcPlural(I.flows.length, 'flow')}.`,
    ...I.walk.map(id => fcNodeName(I, I.N.get(id)) + '.'), ...I.lines.map(e => fcLineName(I, e) + '.')].join('\n');
}

/* ---- editing: each hook returns commands, null to leave the gesture to the default, or { error } for the hint line ---- */
const fcId = (model, base) => { const used = new Set(); JSON.stringify(model, (k, v) => { if (k === 'id' && typeof v === 'string') used.add(v); return v; });
  let k = 1; while (used.has(base + k)) k++; return base + k; }; // as the canvas names a line: 'flow1'
// connect: a flow joins two flowchart nodes (refused otherwise); a decision's second exit is labelled to answer its first,
// yes then no, and an unlabelled first exit becomes yes
function fcConnect(model, view, from, to, at, line) {
  if (!FC_OBJ(view) || !FC_OBJ(line) || line.type !== 'flow.Flow') return null;
  const I = fcIndex(model, null), bad = [from, to].find(id => !I.N.has(id) || !FC_NODES.includes(I.N.get(id).type));
  if (bad != null) return { error: `flow-ends: a flow joins two flowchart nodes, and ${fcCalled(I.N.get(bad))} is not one` };
  const o = [...I.E.values()].filter(e => e.type === 'flow.Flow' && e.from === from);
  if (I.N.get(from).type !== 'flow.Decision' || o.length !== 1) return null;
  const was = FC_TXT(o[0].label).toLowerCase(), label = was === 'yes' || !was ? 'no' : was === 'no' ? 'yes' : null;
  if (!label) return null;
  return [...(was ? [] : [{ op: 'set', id: o[0].id, path: 'label', value: 'yes' }]), { op: 'add', element: { id: fcId(model, 'flow'), type: 'flow.Flow', from, to, label }, view: view.id }];
}
// moveTo: a line dragged (or Alt + arrows on it) is refused, said on the hint line: a flow follows its ends. A view with no direction is laid out down, which the canvas's drop reads as laid out right (render.js hintAt reads
// a view that says down): the pin is read here with the axes turned, as hintAt reads one. Anything else: null, the default
function fcMoveTo(model, view, id, at) {
  if (FC_ARR(model && model.edges).some(e => FC_OBJ(e) && e.id === id)) return { error: 'A flow follows its nodes: move a node instead' };
  if (!FC_OBJ(view) || view.direction != null || !FC_OBJ(at) || !Array.isArray(at.pt) || !FC_OBJ(at.geo)) return null;
  const ns = FC_ARR(at.geo.nodes).filter(m => FC_OBJ(m) && Number.isFinite(m.col) && Number.isFinite(m.row) && !m.aside), n = ns.find(m => m.id === id);
  if (!n) return null;
  const [y, x] = at.pt, X = m => m.y + m.h / 2, Y = m => m.x, cols = [...new Set(ns.map(m => m.col))].sort((a, b) => a - b);
  const mid = c => { const k = ns.filter(m => m.col === c); return k.reduce((s, m) => s + X(m), 0) / k.length; };
  const first = cols[0], last = cols.at(-1), step = cols.length > 1 ? (mid(last) - mid(first)) / (last - first) : 260;
  let col = first, best = Infinity; cols.forEach(c => { const d = Math.abs(mid(c) - x); if (d < best) { best = d; col = c; } });
  if (x > mid(last) + step / 2) col = last + Math.round((x - mid(last)) / step); else if (x < mid(first) - step / 2) col = Math.max(0, first - Math.round((mid(first) - x) / step));
  const a = ns[0], b = ns.find(m => m.row !== a.row), pitch = b ? (Y(b) - Y(a)) / (b.row - a.row) : 108, row = Math.max(0, Math.round((y - (Y(a) - a.row * pitch) - 32) / pitch));
  return col === n.col && row === n.row ? [] : [{ op: 'set', view: view.id, path: ['layout', id], value: [col, row] }];
}

/* ---- the type ---- */
const FC_TYPE = registerDiagramType('flowchart', {
  title: 'flowchart',
  elements: [...FC_NODES, 'uml.Comment'].map(type => ({ type, label: FC_LOOK[type][1] })),
  lines: [{ type: 'flow.Flow', label: 'Flow' }, { type: 'uml.CommentLink', label: 'Comment link' }],
  layout: fcGeo,
  validate: fcProblems,
  rules: FC_RULES,
  describe: fcDescribe,
  // F2 on a node or a flow sets its label: the default
  edits: { connect: fcConnect, moveTo: fcMoveTo },
  // the PDF's tables: a node's symbol; a line's text, which flags a decision's exit with no label (milestone 2 §9)
  word: (model, id) => { const x = FC_ARR(model && model.nodes).find(n => FC_OBJ(n) && n.id === id); return x && Object.hasOwn(FC_LOOK, x.type) ? FC_LOOK[x.type][1] : null; },
  text: (model, view, id) => { const by = x => FC_ARR(x).find(y => FC_OBJ(y) && y.id === id), e = by(model && model.edges), d = e && e.type === 'flow.Flow' && FC_ARR(model.nodes).find(n => FC_OBJ(n) && n.id === e.from);
    return e && !FC_TXT(e.label) && d && d.type === 'flow.Decision' ? `an exit of ${fcCalled(d)} with no label` : null; },
});
/* ---------- the data flow diagram, dfd (work package M2.4, notes/milestone-2.md §4.3, §6.1, §6.4, §7.3) ----------
   Processes, data stores and external entities, joined by data flows; comments. Two skins on one geometry (§4.3): each
   node is sized for the larger of its Yourdon and its Gane and Sarson look, and its shape's name carries the skin
   (dfd-process-yourdon), so a change of view.notation repaints and lays nothing out (`shape` is no geometry, `notation`
   no view geometry). Numbers are stored (props.number) and checked under their parent process's; a process that opens a
   level (opensView, a dfd view whose parent is the view the process is on) balances against it (§6.4). D on a selected
   process that opens no view makes its level, balanced from the start (§6.1). Laid out by layoutTyped from the host's
   ranking, repair and reroute off (S19). Ships in lib/umlimator-all.js only. */

const DFD_OBJ = x => x !== null && typeof x === 'object' && !Array.isArray(x), DFD_ARR = x => (Array.isArray(x) ? x : []);
const DFD_HAS = x => x != null && String(x).trim() !== '';
const dfdNum = x => (DFD_OBJ(x && x.props) && DFD_HAS(x.props.number) ? String(x.props.number).trim() : '');
const dfdPlural = (k, w) => `${k} ${k === 1 ? w : w + 's'}`;
const DFD_LINES = ['dfd.DataFlow', 'uml.CommentLink'];
const DFD_KIND = { 'dfd.Process': 'process', 'dfd.DataStore': 'store', 'dfd.ExternalEntity': 'entity' };
const DFD_WORD = { 'dfd.Process': 'Process', 'dfd.DataStore': 'Data store', 'dfd.ExternalEntity': 'External entity', 'uml.Comment': 'Comment' };
const dfdSkin = view => (view && view.notation === 'gane-sarson' ? 'gane-sarson' : 'yourdon');

/* ---- the shapes (§4.3): one size for both skins; each draws its number and name inside its box ---- */
const DF = { px: 12, lh: 16, nmax: 160, num: 11, numh: 14, pad: 10, k: 1.42, band: 22, shadow: 4, minW: 96 };
const dfdName = (t, k) => flowWrap(t, DF.px, DF.nmax, k);
const dfdTextW = ls => Math.max(0, ...ls.map(l => textW(l, DF.px)));
const dfdText = (x, y, t, px, wt, fill, max, cls, anchor = 'middle', more = '') => `<text x="${r2(x)}" y="${r2(y)}" text-anchor="${anchor}" class="${cls}" fill="${fill}"${more} style="font:${wt} ${px}px var(--um-sans)">${esc(fit(t, px, max))}</text>`;
const dfdNode = (n, kind, inner) => `<g class="node dfd-${kind}" data-id="${esc(n.id)}" data-shape="${n.shape}" tabindex="-1" role="img" aria-label="${esc(n.aria || n.label || '')}">${inner}</g>`;
const dfdBody = (d, c, f) => `<path d="${d}" class="n-mask"/><path d="${d}" class="n-body" fill="${f}" stroke="${c}"/>`;
const dfdRect = (x, y, w, h) => `M${r2(x)} ${r2(y)}H${r2(x + w)}V${r2(y + h)}H${r2(x)}Z`;
const dfdSquare = { out: (n, d = 0) => dfdRect(n.x - d, n.y - d, n.w + 2 * d, n.h + 2 * d), inset: () => 0 };
// name lines centred in the band [y0, y1] of the box, the first with data-o (F2's field goes over it)
const dfdNameSvg = (n, ls, cx, y0, y1, max) => { const y = (y0 + y1) / 2 - ls.length * DF.lh / 2;
  return ls.map((l, i) => dfdText(cx, y + i * DF.lh + 12, l, DF.px, 600, 'var(--um-text)', max, 'c-name', 'middle', i ? '' : ` data-o="${esc(n.id)}"`)).join(''); };

// a process: Yourdon's ellipse round its number over its name (the text block 1.42 times, so its corners fit inside it), or
// Gane and Sarson's rounded rectangle with the number in a band across its top
const dfdProcParts = n => { const num = String(n.number ?? ''), ls = dfdName(n.label, 3), tw = Math.max(dfdTextW(ls), num ? Math.min(DF.nmax, textW(num, DF.num)) : 0), th = (num ? DF.numh : 0) + ls.length * DF.lh;
  return { num, ls, w: Math.ceil(Math.max(DF.minW, tw * DF.k + 16, tw + 2 * DF.pad)), h: Math.ceil(Math.max(56, th * DF.k + 12, DF.band + ls.length * DF.lh + 2 * DF.pad)) }; };
const dfdProcess = skin => ({
  size: n => { const p = dfdProcParts(n); return { w: p.w, h: p.h }; },
  ...(skin === 'yourdon' ? { out: SHAPE.ellipse.out, inset: SHAPE.ellipse.inset } : { out: SHAPE.box.out, inset: SHAPE.box.inset }),
  draw(n, c, f) {
    const { num, ls } = dfdProcParts(n), cx = n.x + n.w / 2;
    if (skin === 'yourdon') { const max = (n.w - 16) / DF.k, y0 = n.y + n.h / 2 - ((num ? DF.numh : 0) + ls.length * DF.lh) / 2;
      return dfdNode(n, 'process', dfdBody(SHAPE.ellipse.out(n), c, f) + (num ? dfdText(cx, y0 + 10.5, num, DF.num, 500, 'var(--um-muted)', max, 'c-st') : '')
        + dfdNameSvg(n, ls, cx, y0 + (num ? DF.numh : 0), n.y + n.h / 2 + ((num ? DF.numh : 0) + ls.length * DF.lh) / 2, max)); }
    const max = n.w - 2 * DF.pad;
    return dfdNode(n, 'process', dfdBody(SHAPE.box.out(n), c, f) + `<path d="M${r2(n.x)} ${r2(n.y + DF.band)}H${r2(n.x + n.w)}" class="n-det" stroke="${c}"/>`
      + (num ? dfdText(cx, n.y + 15, num, DF.num, 500, 'var(--um-muted)', max, 'c-st') : '') + dfdNameSvg(n, ls, cx, n.y + DF.band, n.y + n.h, max));
  },
});
// a data store: Yourdon's two lines with the number before the name, or Gane and Sarson's rectangle open on the right,
// its number in an id box on the left
const dfdStoreParts = n => { const num = String(n.number ?? ''), ls = dfdName(n.label, 2), nw = num ? Math.min(DF.nmax, textW(num, DF.num)) : 0, ib = Math.max(28, Math.ceil(nw) + 12), tw = dfdTextW(ls);
  return { num, ls, nw, ib, w: Math.ceil(Math.max(DF.minW, ib + tw + 2 * DF.pad, nw + 8 + tw + 2 * DF.pad)), h: Math.max(36, ls.length * DF.lh + 16) }; };
const dfdStore = skin => ({
  size: n => { const p = dfdStoreParts(n); return { w: p.w, h: p.h }; },
  ...dfdSquare,
  draw(n, c, f) {
    const { num, ls, nw, ib } = dfdStoreParts(n), { x, y, w, h } = n, mask = `<path d="${dfdRect(x, y, w, h)}" class="n-mask"/>`;
    if (skin === 'yourdon') { const tx = x + DF.pad + (num ? nw + 8 : 0), max = x + w - DF.pad - tx;
      return dfdNode(n, 'store', mask + `<path d="${dfdRect(x, y, w, h)}" fill="${f}" stroke="none"/><path d="M${r2(x)} ${r2(y)}H${r2(x + w)}M${r2(x)} ${r2(y + h)}H${r2(x + w)}" class="n-body" fill="none" stroke="${c}"/>`
        + (num ? dfdText(x + DF.pad, y + h / 2 + 4, num, DF.num, 500, 'var(--um-muted)', nw + 1, 'c-st', 'start') : '') + dfdNameSvg(n, ls, tx + max / 2, y, y + h, max)); }
    const max = w - ib - 2 * DF.pad;
    return dfdNode(n, 'store', mask + `<path d="${dfdRect(x, y, w, h)}" fill="${f}" stroke="none"/><path d="M${r2(x + w)} ${r2(y)}H${r2(x)}V${r2(y + h)}H${r2(x + w)}M${r2(x + ib)} ${r2(y)}V${r2(y + h)}" class="n-body" fill="none" stroke="${c}"/>`
      + (num ? dfdText(x + ib / 2, y + h / 2 + 4, num, DF.num, 500, 'var(--um-muted)', ib - 6, 'c-st') : '') + dfdNameSvg(n, ls, x + ib + DF.pad + max / 2, y, y + h, max));
  },
});
// an external entity: a rectangle; in Gane and Sarson a 4 px shadow inside the box, at its right and bottom
const dfdEntityParts = n => { const ls = dfdName(n.label, 3); return { ls, w: Math.ceil(Math.max(DF.minW, dfdTextW(ls) + 2 * DF.pad + DF.shadow)), h: ls.length * DF.lh + 16 + DF.shadow }; };
const dfdEntity = skin => ({
  size: n => { const p = dfdEntityParts(n); return { w: p.w, h: p.h }; },
  ...dfdSquare,
  draw(n, c, f) {
    const { ls } = dfdEntityParts(n), { x, y, w, h } = n, s = skin === 'yourdon' ? 0 : DF.shadow;
    const body = s ? `<path d="${dfdRect(x, y, w, h)}" class="n-mask"/><path d="${dfdRect(x + s, y + s, w - s, h - s)}" class="n-det" fill="${c}" stroke="${c}"/><path d="${dfdRect(x, y, w - s, h - s)}" class="n-body" fill="${f}" stroke="${c}"/>` : dfdBody(dfdRect(x, y, w, h), c, f);
    return dfdNode(n, 'entity', body + dfdNameSvg(n, ls, x + (w - s) / 2, y, y + h - s, w - s - 2 * DF.pad));
  },
});
for (const skin of ['yourdon', 'gane-sarson']) for (const [kind, make] of [['process', dfdProcess], ['store', dfdStore], ['entity', dfdEntity]]) {
  const S = SHAPE[`dfd-${kind}-${skin}`] = make(skin); S.face = n => [n.y, n.y + n.h]; S.ports = (n, side, k = 1) => portsOn(S, n, side, k); }

/* ---- the model read: its elements, the lines a view draws, its levels ---- */
function dfdIndex(model) {
  const at = new Map(), path = new Map(), views = new Map();
  DFD_ARR(model && model.nodes).forEach((x, i) => { if (DFD_OBJ(x) && typeof x.id === 'string' && !at.has(x.id)) { at.set(x.id, x); path.set(x.id, `nodes[${i}]`); } });
  DFD_ARR(model && model.views).forEach(v => { if (DFD_OBJ(v) && typeof v.id === 'string' && !views.has(v.id)) views.set(v.id, v); });
  const flows = DFD_ARR(model && model.edges).map((e, i) => [e, `edges[${i}]`]).filter(([e]) => DFD_OBJ(e) && e.type === 'dfd.DataFlow');
  const ty = id => (at.get(id) || {}).type, proc = id => ty(id) === 'dfd.Process';
  const name = id => { const x = at.get(id); if (!x) return String(id); const k = dfdNum(x); return (k ? k + ' ' : '') + String(x.label ?? x.id); };
  const q = id => `${(DFD_WORD[ty(id)] || 'element').toLowerCase()} "${name(id)}"`;
  // a level: the view a process opens, its parent view, and its own processes, those it shows and its parent view does not
  const level = p => { const v = views.get((at.get(p) || {}).opensView), pv = v && views.get(v.parent), up = new Set(DFD_ARR(pv && pv.nodeIds));
    return v ? { v, pv, up, kids: DFD_ARR(v.nodeIds).filter(id => proc(id) && id !== p && !up.has(id)) } : null; };
  const parentOf = vid => [...at.values()].find(x => x.type === 'dfd.Process' && x.opensView === vid) || null; // the process a view is the level of
  return { at, path, views, flows, ty, proc, name, q, level, parentOf };
}
// the lines drawn: those the view lists, or with no list the model's of this type's kinds, between two nodes it shows; on a
// level (a view a process opens) with no list, not those with both ends on its parent view: they are the parent level's,
// and reach the level only through its own processes (Yourdon and DeMarco's levelling)
function dfdLines(model, view) {
  const E = new Map(); DFD_ARR(model.edges).forEach(e => { if (DFD_OBJ(e) && typeof e.id === 'string' && !E.has(e.id)) E.set(e.id, e); });
  const shown = new Set(DFD_ARR(view.nodeIds)), listed = Array.isArray(view.edges), list = listed ? view.edges.map(x => (typeof x === 'string' ? E.get(x) : x)) : [...E.values()].filter(e => DFD_LINES.includes(e.type));
  const lv = !listed && view.parent !== view.id && DFD_ARR(model.nodes).some(x => DFD_OBJ(x) && x.type === 'dfd.Process' && x.opensView === view.id);
  const up = new Set(lv ? DFD_ARR((DFD_ARR(model.views).find(v => DFD_OBJ(v) && v.id === view.parent) || {}).nodeIds) : []);
  return list.filter(e => DFD_OBJ(e) && typeof e.id === 'string' && shown.has(e.from) && shown.has(e.to) && !(up.has(e.from) && up.has(e.to)));
}
// accessible names (A1): "Process 1 Take order, opens level 1 Take order, 2 flows in, 2 out"; a flow: "Data flow basket from Customer to 1 Take order"
function dfdNodeName(I, id, lines) {
  const x = I.at.get(id); if (x.type === 'uml.Comment') return 'Comment: ' + String(x.label ?? '');
  const ins = lines.filter(e => e.type === 'dfd.DataFlow' && e.to === id && e.from !== id).length, outs = lines.filter(e => e.type === 'dfd.DataFlow' && e.from === id && e.to !== id).length;
  const v = x.type === 'dfd.Process' && I.views.get(x.opensView);
  return `${DFD_WORD[x.type] || String(x.type).split('.').pop()} ${I.name(id)}${v ? `, opens level ${v.title || v.id}` : ''}, ${dfdPlural(ins, 'flow')} in, ${outs} out`;
}
const dfdLineName = (I, e) => `${e.type === 'dfd.DataFlow' ? 'Data flow' : 'Comment link'}${DFD_HAS(e.label) ? ' ' + e.label : ''} from ${I.name(e.from)} to ${I.name(e.to)}`;
// reading order: the processes by number, then the stores, the entities and the rest as the view lists them, then the lines
function dfdOrder(I, ids, lines) {
  const rank = id => ['dfd.Process', 'dfd.DataStore', 'dfd.ExternalEntity'].indexOf(I.ty(id)) + 1 || 4, byNum = (a, b) => dfdNum(I.at.get(a)).localeCompare(dfdNum(I.at.get(b)), undefined, { numeric: true });
  return [...[...ids].sort((a, b) => rank(a) - rank(b) || (rank(a) === 1 ? byNum(a, b) : 0)), ...lines.map(e => e.id)];
}

/* ---- the legend: each symbol drawn, in the view's skin, and the line kinds ---- */
const DFD_GLYPH = {
  'process-yourdon': '<ellipse cx="14" cy="8" rx="12" ry="6.5" fill="var(--um-panel)"/>', 'process-gane-sarson': '<rect x="3" y="1.5" width="22" height="13" rx="3" fill="var(--um-panel)"/><path d="M3 5.5H25"/>',
  'store-yourdon': '<path d="M2 3H26M2 13H26"/>', 'store-gane-sarson': '<path d="M26 3H2V13H26M8 3V13"/>',
  'entity-yourdon': '<rect x="3" y="2" width="22" height="12" fill="var(--um-panel)"/>', 'entity-gane-sarson': '<rect x="5" y="4" width="21" height="11" fill="var(--um-muted)"/><rect x="3" y="2" width="21" height="11" fill="var(--um-panel)"/>',
  'dfd.DataFlow': '<path d="M2 8H17"/><path d="M17 4L26 8L17 12Z" fill="var(--um-muted)"/>', 'uml.CommentLink': '<path d="M2 8H26" stroke-dasharray="3 2"/>',
};
const DFD_SAYS = { process: 'transforms the data flowing in into the data flowing out', store: 'holds data at rest', entity: 'outside the system: a source or a sink of data',
  'dfd.DataFlow': 'data moving, named by what it carries', 'uml.CommentLink': 'what a comment is about' };
const dfdLegendItem = (glyph, name, says) => `<span class="lgi" title="${esc(name + ' — ' + says)}"><svg class="lgs" viewBox="0 0 28 16" aria-hidden="true"><g stroke="var(--um-muted)" stroke-width="1.4" stroke-linejoin="round" fill="none">${glyph}</g></svg><b>${esc(name)}</b><span>${esc(says)}</span></span>`;
const dfdLegend = (I, ids, lines, skin) => [
  ...['process', 'store', 'entity'].filter(k => ids.some(id => DFD_KIND[I.ty(id)] === k)).map(k => dfdLegendItem(DFD_GLYPH[`${k}-${skin}`], DFD_WORD[Object.keys(DFD_KIND).find(t => DFD_KIND[t] === k)], DFD_SAYS[k])),
  ...DFD_LINES.filter(t => lines.some(e => e.type === t)).map(t => dfdLegendItem(DFD_GLYPH[t], t === 'dfd.DataFlow' ? 'Data flow' : 'Comment link', DFD_SAYS[t]))];

/* ---- the view laid out (§7): labels cut at 280 with room made for them (labelGaps); a gap of 64 px, as 48 laid a label of
   22-data-flow.json on a line, down (the note's §7.3, amended) ---- */
const DFD_END = { 'dfd.DataFlow': { from: 'none', to: 'arrow' }, 'uml.CommentLink': { from: 'none', to: 'none', dashed: true } };
function dfdGeo({ model, view, pos, memo }) {
  const I = dfdIndex(model), ids = DFD_ARR(view.nodeIds).filter((id, k, a) => I.at.has(id) && a.indexOf(id) === k), lines = dfdLines(model, view), skin = dfdSkin(view), P = id => (pos && Object.hasOwn(pos, id) ? pos[id] : [0, 0]);
  const nodes = ids.map(id => { const x = I.at.get(id), k = DFD_KIND[x.type];
    const d = { id, label: String(x.label ?? id), type: x.type || 'dfd.Process', kind: 'file', ...(k ? { shape: `dfd-${k}-${skin}`, number: dfdNum(x) } : x.type === 'uml.Comment' ? { shape: 'note' } : { shape: 'classifier', compartments: [] }),
      aria: dfdNodeName(I, id, lines), col: P(id)[0], row: P(id)[1] };
    return { ...d, ...SHAPE[d.shape].size(d) }; });
  const edges = lines.map(e => ({ id: e.id, _id: e.id, type: e.type, from: e.from, to: e.to, ...(DFD_HAS(e.label) ? { label: String(e.label), cut: 280 } : {}),
    end: DFD_END[e.type] || DFD_END['dfd.DataFlow'], aria: dfdLineName(I, e), ...(DFD_OBJ(e.style) || typeof e.style === 'string' ? { style: e.style } : {}) }));
  const g = layoutTyped({ nodes, edges, direction: view.direction === 'down' ? 'down' : 'right', gap: 64, rgap: 56, labelGaps: true, repair: false, reroute: false }, memo);
  return { ...g, legend: dfdLegend(I, ids, lines, skin), order: dfdOrder(I, ids, lines) }; // a new object: what layoutTyped returned is never edited (§2.6)
}

/* ---- validators (§6.4, §7.3). Each problem: { level, rule, path, message, ids }; on the whole model, once a type ---- */
const DFD_RULES = {
  'dfd-flow-process': 'a flow has a process at one end at least: no flow between two stores, two entities, or an entity and a store',
  'dfd-process-io': 'a process has a flow in and a flow out',
  'dfd-flow-label': 'a flow to or from a process has a label',
  'dfd-numbers': 'a level\'s processes are numbered under their parent process\'s (1.1, 1.2 under 1); no number is used twice',
  'dfd-balance': 'the flows between a process and the rest of its level match its level\'s flows across the level\'s edge, by label, far end and direction',
  'dfd-level': 'a process opens a dfd view whose parent is a view showing the process; the level is that process\'s alone and does not show it',
};
function dfdProblems(model) {
  const I = dfdIndex(model), out = [], say = (level, rule, path, ids, msg) => out.push({ level, rule, path, ids: ids.filter(x => x != null), message: `${rule}: ${msg}` });
  const procs = [...I.at.values()].filter(x => x.type === 'dfd.Process');
  I.flows.forEach(([e, path]) => { if (!I.at.has(e.from) || !I.at.has(e.to)) return;
    if (!I.proc(e.from) && !I.proc(e.to)) say('warning', 'dfd-flow-process', path, [e.id, e.from, e.to], `${e.id} runs from ${I.q(e.from)} to ${I.q(e.to)}: a flow has a process at one end at least`);
    else if (!DFD_HAS(e.label)) say('warning', 'dfd-flow-label', path, [e.id], `${e.id}, from ${I.q(e.from)} to ${I.q(e.to)}, has no label: a flow is named by the data it carries`); });
  procs.forEach(p => { const has = w => I.flows.some(([e]) => e[w] === p.id && e[w === 'from' ? 'to' : 'from'] !== p.id), miss = ['in', 'out'].filter((k, i) => !has(i ? 'from' : 'to'));
    if (miss.length) say('warning', 'dfd-process-io', I.path.get(p.id), [p.id], `${I.q(p.id)} has no flow ${miss.join(' and no flow ')}`); });
  // numbers: none used twice among processes, nor among stores; a level's processes under their parent's
  for (const t of ['dfd.Process', 'dfd.DataStore']) { const by = new Map(); [...I.at.values()].filter(x => x.type === t && dfdNum(x)).forEach(x => by.set(dfdNum(x), [...(by.get(dfdNum(x)) || []), x.id]));
    by.forEach((list, k) => { if (list.length > 1) say('warning', 'dfd-numbers', I.path.get(list[1]), list, `${list.length} ${t === 'dfd.Process' ? 'processes' : 'stores'} are numbered ${k}: ${list.map(id => JSON.stringify(String(I.at.get(id).label ?? id))).join(', ')}`); }); }
  procs.forEach(p => { const L = I.level(p.id), n = dfdNum(p); if (!L || L.v.diagram !== 'dfd' || !n || I.parentOf(L.v.id) !== p) return;
    L.kids.filter(id => !new RegExp(`^${n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\.\\d+$`).test(dfdNum(I.at.get(id)))).forEach(id =>
      say('warning', 'dfd-numbers', I.path.get(id), [id, p.id], `${I.q(id)}, on the level of ${I.q(p.id)}, is numbered ${dfdNum(I.at.get(id)) || 'nothing'}: its number is ${n}.1, ${n}.2, …`)); });
  // a level: a dfd view whose parent shows the process; then balanced (§6.4), each pair by label, far end and direction
  procs.filter(p => p.opensView != null).forEach(p => { const L = I.level(p.id), path = I.path.get(p.id);
    const first = L && I.parentOf(L.v.id), bad = !L ? `opens "${p.opensView}", which is no view` : L.v.diagram !== 'dfd' ? `opens "${L.v.id}", a ${L.v.diagram || 'map'} view, not a level`
      : L.v === L.pv ? `opens "${L.v.id}", whose parent view is itself` : !L.up.has(p.id) ? `opens "${L.v.id}", whose parent view ${L.pv ? `"${L.pv.id}" does not show it` : `is ${L.v.parent == null ? 'not given' : `"${L.v.parent}", which is no view`}`}`
        : first !== p ? `opens "${L.v.id}", which ${I.q(first.id)} opens already: a level is one process's` : DFD_ARR(L.v.nodeIds).includes(p.id) ? `opens "${L.v.id}", which shows the process itself: its level shows its parts` : '';
    if (bad) return say('warning', 'dfd-level', path, [p.id, ...(first && first !== p ? [first.id] : [])], `${I.q(p.id)} ${bad}`);
    // the flows each view draws: the process's on its parent view; on the level, those across the edge of its own processes,
    // but to a store the parent view does not show (a local store)
    const kids = new Set(L.kids), key = (e, mine) => { const o = e.from === mine ? e.to : e.from; return [e.from === mine ? 'out' : 'in', o, String(e.label ?? '').trim()]; };
    const drawn = v => dfdLines(model, v).filter(e => e.type === 'dfd.DataFlow');
    const outer = drawn(L.pv).filter(e => (e.from === p.id) !== (e.to === p.id)).map(e => [e, key(e, p.id)]);
    const inner = drawn(L.v).filter(e => { const o = kids.has(e.from) ? e.to : e.from; return kids.has(e.from) !== kids.has(e.to) && o !== p.id && (L.up.has(o) || I.ty(o) !== 'dfd.DataStore'); }).map(e => [e, key(e, kids.has(e.from) ? e.from : e.to)]);
    const left = [...inner], miss = outer.filter(([, k]) => { const i = left.findIndex(([, j]) => j.join('\u0001') === k.join('\u0001')); if (i < 0) return true; left.splice(i, 1); return false; });
    if (!miss.length && !left.length) return;
    const said = ([e, [dir, o, l]]) => `"${l}" ${dir === 'in' ? 'in from' : 'out to'} ${I.q(o)} (${e.id})`, lv = `level "${L.v.title || L.v.id}"`;
    say('error', 'dfd-balance', path, [p.id, ...miss.map(([e]) => e.id), ...left.map(([e]) => e.id)], `${I.q(p.id)} does not balance with ${lv}: ${[
      miss.length ? `its flow${miss.length > 1 ? 's' : ''} ${miss.map(said).join(', ')} ${miss.length > 1 ? 'have' : 'has'} none at the level` : '',
      left.length ? `the level's flow${left.length > 1 ? 's' : ''} ${left.map(said).join(', ')} ${left.length > 1 ? 'are' : 'is'} not the process's` : ''].filter(Boolean).join('; ')}`); });
  return out;
}

/* ---- describe(): the view in sentences, each element by its accessible name in reading order, then each line ---- */
function dfdDescribe(model, viewId) {
  const v = DFD_ARR(model && model.views).find(x => DFD_OBJ(x) && x.id === viewId); if (!v) throw new Error(`umlimator: no view ${JSON.stringify(viewId)}`);
  const I = dfdIndex(model), ids = DFD_ARR(v.nodeIds).filter((id, k, a) => I.at.has(id) && a.indexOf(id) === k), lines = dfdLines(model, v), by = new Map(lines.map(e => [e.id, e])), up = I.parentOf(v.id);
  return [`${v.title || v.id}: a data flow diagram${up ? `, the level of ${I.q(up.id)},` : ''} of ${dfdPlural(ids.length, 'element')} and ${dfdPlural(lines.length, 'line')}.`,
    ...dfdOrder(I, ids, lines).map(id => (by.has(id) ? dfdLineName(I, by.get(id)) : dfdNodeName(I, id, lines)) + '.')].join('\n');
}

/* ---- editing (§6.1, §7.3) ---- */
const dfdUsed = model => { const used = new Set(); JSON.stringify(model, (k, v) => { if (k === 'id' && typeof v === 'string') used.add(v); return v; }); return used; };
// a free id: base, else base-2, base-3, …; numbered (the palette's): base1, base2, …. Taken once given
const dfdFree = (used, base, numbered) => { let k = 1, id = numbered ? base + 1 : base; while (used.has(id)) id = base + (numbered ? '' : '-') + ++k; used.add(id); return id; };
// the next free number of a type after pre: pre1, pre2, …
const dfdFreeNum = (I, type, pre) => { const taken = new Set([...I.at.values()].filter(x => x.type === type).map(dfdNum)); let k = 1; while (taken.has(pre + k)) k++; return pre + k; };
// the next free number: under the view's parent process (1.1, 1.2 under 1), else 1, 2, …; a store's D1, D2, …
function dfdNextNumber(model, view, type) {
  const I = dfdIndex(model), up = type === 'dfd.Process' && I.parentOf(view.id);
  return dfdFreeNum(I, type, type === 'dfd.DataStore' ? 'D' : up && dfdNum(up) ? dfdNum(up) + '.' : '');
}
// the palette's add: a process or a store with the next free number
function dfdAdd(model, view, entry, label) {
  if (!['dfd.Process', 'dfd.DataStore'].includes(entry.type)) return null;
  const id = dfdFree(dfdUsed(model), entry.type === 'dfd.Process' ? 'process' : 'store', true);
  return [{ op: 'add', element: { id, type: entry.type, ...(label ? { label } : {}), props: { number: dfdNextNumber(model, view, entry.type) } }, view: view.id }];
}
/* D on a selected process that opens no view (§6.1): its level, in one transaction. The new view (<id>-level, the next
   free) shows the far ends of the process's flows drawn on this view and one child process, numbered <n>.1 (the next
   free under <n>) and named as its parent; each of those flows is copied with the process's end moved to the child, so the level balances from the start */
function dfdKey(model, view, ids, key) {
  if (key !== 'd' && key !== 'D') return null;
  const I = dfdIndex(model), p = ids.length === 1 && I.proc(ids[0]) ? I.at.get(ids[0]) : null; if (!p) return null;
  if (p.opensView != null) return { error: `${I.q(p.id)} opens "${p.opensView}" already: Enter opens it` };
  const used = dfdUsed(model), n = dfdNum(p), kn = dfdFreeNum(I, 'dfd.Process', n ? n + '.' : '');
  const flows = dfdLines(model, view).filter(e => e.type === 'dfd.DataFlow' && (e.from === p.id) !== (e.to === p.id));
  const vid = dfdFree(new Set(DFD_ARR(model.views).filter(DFD_OBJ).map(v => v.id)), p.id + '-level'), kid = dfdFree(used, `${p.id}-${kn}`), title = `${n ? n + ' ' : ''}${p.label ?? p.id}`;
  return { commands: [
    { op: 'addView', view: { id: vid, diagram: 'dfd', title, parent: view.id, ...(view.notation != null ? { notation: view.notation } : {}), ...(view.direction != null ? { direction: view.direction } : {}),
      nodeIds: [...new Set(flows.map(e => (e.from === p.id ? e.to : e.from)))] } },
    { op: 'add', element: { id: kid, type: 'dfd.Process', ...(p.label != null ? { label: p.label } : {}), props: { number: kn } }, view: vid },
    ...flows.map(e => ({ op: 'add', element: { id: dfdFree(used, `${e.id}-${kn}`), type: 'dfd.DataFlow', from: e.from === p.id ? kid : e.from, to: e.to === p.id ? kid : e.to, ...(e.label != null ? { label: e.label } : {}) } })),
    { op: 'set', id: p.id, path: 'opensView', value: vid }],
  say: `Made level ${title}, balanced with ${dfdPlural(flows.length, 'flow')}: Enter opens it` };
}

const DFD_NUMBER = { key: 'number', label: 'Number', kind: 'text' };
const DFD_TYPE = registerDiagramType('dfd', {
  title: 'data flow diagram',
  elements: [['dfd.Process', 'Process', 'dfd'], ['dfd.DataStore', 'Data store'], ['dfd.ExternalEntity', 'External entity'], ['uml.Comment', 'Comment']].map(([type, label, opens]) => ({ type, label, ...(opens ? { opens } : {}) })),
  lines: [{ type: 'dfd.DataFlow', label: 'Data flow' }, { type: 'uml.CommentLink', label: 'Comment link' }],
  props: { 'dfd.Process': [DFD_NUMBER], 'dfd.DataStore': [DFD_NUMBER], 'dfd.ExternalEntity': [], 'dfd.DataFlow': [], 'uml.CommentLink': [] },
  layout: dfdGeo,
  validate: dfdProblems,
  rules: DFD_RULES,
  describe: dfdDescribe,
  edits: { add: dfdAdd, key: dfdKey },
  // the PDF's tables (§9): an element's kind; a process's number and the level it opens, a store's number
  word: (model, id) => { const x = dfdIndex(model).at.get(id); return x && Object.hasOwn(DFD_WORD, x.type) ? DFD_WORD[x.type] : null; },
  rows: (model, view, id) => { const I = dfdIndex(model), x = I.at.get(id); if (!x || !['dfd.Process', 'dfd.DataStore'].includes(x.type)) return null;
    const v = x.type === 'dfd.Process' && I.views.get(x.opensView); return [...(dfdNum(x) ? [`number ${dfdNum(x)}`] : []), ...(v ? [`opens level ${v.title || v.id}`] : [])]; },
});
/* ---------- the information flow diagram, uml.information-flow (work package M2.5, notes/milestone-2.md §7.4) ----------
   Classes and interfaces (the class type's classifier, name only), components (src/uml/structure.js's look) and actors (the
   use case type's figure), each read only; information items, a classifier with a small filled triangle at its top right
   (UML 2.5.1 §20.2.4); comments. Information flows: a dashed line with an open arrow, its label «flow» then what it conveys
   by name (`Order, Card details`), after its own name when it has one (`place: Order`), cut at 280; comment links.
   props.conveyed is a declared reference (refs: drop), so deleting an element drops it from every flow. Laid out by
   layoutTyped from the host's ranking: gap 48 with gapAfter's widening, labelGaps, repair and reroute off (S19). Ships in
   lib/umlimator-all.js only. */

const IF_OBJ = x => x !== null && typeof x === 'object' && !Array.isArray(x), IF_ARR = x => (Array.isArray(x) ? x : []);
const IF_HAS = x => x != null && x !== '';
const ifName = x => String(x.label ?? x.id);
const ifStereo = x => IF_ARR(IF_OBJ(x.props) ? x.props.stereotypes : null).filter(IF_HAS).map(String);
const ifPlural = (k, w) => `${k} ${k === 1 ? w : w + 's'}`;
const ifAnd = a => (a.length < 2 ? a.join('') : `${a.slice(0, -1).join(', ')} and ${a.at(-1)}`);
const IF_ENDS = ['uml.Class', 'uml.Interface', 'uml.Component', 'uml.Actor']; // what a flow joins (§3, §13)
// what a flow may convey: UML 2.5.1 §20.2.4's convey_classifiers, a class, an interface, an information item, a signal or a component
const IF_CONVEY = ['uml.InformationItem', 'uml.Class', 'uml.Interface', 'uml.Component', 'uml.Signal'];
const IF_LINES = ['uml.InformationFlow', 'uml.CommentLink'];
const IF_WORD = { 'uml.Class': 'Class', 'uml.Interface': 'Interface', 'uml.Component': 'Component', 'uml.Actor': 'Actor', 'uml.InformationItem': 'Information item', 'uml.Comment': 'Comment',
  'uml.Signal': 'Signal' };
const ifWord = t => (Object.hasOwn(IF_WORD, t) ? IF_WORD[t] : String(t ?? 'untyped').split('.').pop());
// the keyword over a classifier's name: an interface's, a signal's, and any other kind a view shows its own («useCase»), so none passes for a class
const IF_KEY = { 'uml.Class': null, 'uml.InformationItem': null, 'uml.PrimitiveType': 'primitive' };
const ifKey = t => (Object.hasOwn(IF_KEY, t) ? IF_KEY[t] : String(t ?? '').split('.').pop().replace(/^./, c => c.toLowerCase()) || null);

/* ---- the information item: the classifier, 32 px wider, its centred name kept 8 px clear of the triangle at its top right ---- */
const IF_IT = { pad: 8, name: 13, more: 32 };
// the classifier's own markup, named by n.aria (A1) and by its shape
const ifClassifier = (n, c, f, shape = 'classifier') => SHAPE.classifier.draw(n, c, f).replace(/data-shape="classifier" tabindex="-1" role="img" aria-label="[^"]*"/,
  `data-shape="${shape}" tabindex="-1" role="img" aria-label="${esc(n.aria || n.label || '')}"`);
// a class or an interface: the classifier, named by its accessible name rather than the classifier's own («interface» twice)
SHAPE['if-classifier'] = { ...SHAPE.classifier, draw: (n, c, f) => ifClassifier(n, c, f) };
SHAPE['information-item'] = { ...SHAPE.classifier,
  size: n => { const s = SHAPE.classifier.size(n); return { w: s.w + IF_IT.more, h: s.h }; },
  draw(n, c, f) { const x = n.x + n.w - 16, y = n.y + 6, tri = `<path d="M${r2(x)} ${r2(y)}L${r2(x + 10)} ${r2(y + 5)}L${r2(x)} ${r2(y + 10)}Z" class="if-icon" fill="${c}" stroke="${c}" stroke-linejoin="round"/>`;
    return ifClassifier({ ...n, label: fit(String(n.label ?? ''), IF_IT.name, n.w - 2 * IF_IT.pad - IF_IT.more / 2 - 16) }, c, f, 'information-item').replace(/<\/g>$/, tri + '</g>'); },
};

/* ---- the model read ---- */
function ifIndex(model) {
  const at = new Map(); IF_ARR(model && model.nodes).forEach(n => { if (IF_OBJ(n) && typeof n.id === 'string' && !at.has(n.id)) at.set(n.id, n); });
  const E = IF_ARR(model && model.edges).filter(e => IF_OBJ(e) && typeof e.id === 'string');
  const conveyed = e => IF_ARR(IF_OBJ(e.props) ? e.props.conveyed : null);
  const nm = id => (at.has(id) ? ifName(at.get(id)) : String(id)); // a conveyed id that is gone: said as itself (conveyed-kind)
  return { at, E, conveyed, nm, flowsOf: id => E.filter(e => e.type === 'uml.InformationFlow' && conveyed(e).includes(id)) };
}
// what a flow says: its name, then what it conveys by name ("place: Order, Card details"); the PDF's line text (S17)
const ifSays = (I, e) => `${IF_HAS(e.label) ? e.label + ': ' : ''}${I.conveyed(e).map(I.nm).join(', ')}`;
// the lines drawn: those the view lists, or with no list the model's of this type's kinds, between two elements it shows
function ifLines(I, view, shown) {
  const by = new Map(I.E.map(e => [e.id, e])), list = Array.isArray(view.edges) ? view.edges.map(x => (typeof x === 'string' ? by.get(x) : x)) : I.E.filter(e => IF_LINES.includes(e.type));
  return list.filter(e => IF_OBJ(e) && typeof e.id === 'string' && shown.has(e.from) && shown.has(e.to));
}
const ifShown = (I, view) => [...new Set(IF_ARR(view && view.nodeIds))].filter(id => I.at.has(id));

/* ---- accessible names (§7.4): "Information item Order, conveyed by 4 flows"; "Information flow from Shopper to Storefront,
   conveys Order and Card details" ---- */
function ifNodeName(I, n) {
  if (n.type === 'uml.Comment') return 'Comment: ' + ifName(n);
  const st = ifStereo(n), w = ifWord(n.type), k = I.flowsOf(n.id).length;
  return `${w} ${ifName(n)}${st.length ? ` (${st.join(', ')})` : ''}${k ? `, conveyed by ${ifPlural(k, 'flow')}` : ''}`;
}
function ifLineName(I, e) {
  const ends = `from ${I.nm(e.from)} to ${I.nm(e.to)}`;
  if (e.type === 'uml.CommentLink') return `Comment link ${ends}`;
  if (e.type !== 'uml.InformationFlow') return `Line ${ends}`;
  const c = I.conveyed(e).map(I.nm);
  return `Information flow${IF_HAS(e.label) ? ' ' + e.label : ''} ${ends}${c.length ? ', conveys ' + ifAnd(c) : ''}`;
}

/* ---- the legend. ponytail: copies class.js's legendItem, which it does not export ---- */
const IF_SAYS = { 'uml.InformationFlow': ['Information flow', '«flow»: what travels from one end to the other'], 'uml.CommentLink': ['Comment link', 'what a comment is about'] };
const ifLegend = edges => IF_LINES.filter(t => edges.some(e => e.type === t)).map(t => { const [name, says] = IF_SAYS[t], flow = t === 'uml.InformationFlow';
  return `<span class="lgi" title="${esc(name + ' — ' + says)}"><svg class="lgs" viewBox="0 0 28 16" aria-hidden="true"><g stroke="var(--um-muted)" stroke-width="1.4" stroke-linejoin="round"><path d="M2 8H${flow ? 17 : 26}" stroke-dasharray="3 2"/>${flow ? '<path d="M17 4L26 8L17 12" fill="none"/>' : ''}</g></svg><b>${esc(name)}</b><span>${esc(says)}</span></span>`; });

/* ---- the view laid out ----
   A flow back over two columns or more (a reply that closes a loop: an email to the shopper) leaves its source's bottom and
   comes into its target's bottom, in the layout's axes, under the rows it passes: through the middle it crosses the lines
   between them (15-information-flow.json, right and down). ponytail: one fixed side, not a search; a view whose long back
   flows still cross would take the router's side choice (reroute), which S19 leaves off for the edits' time */
function ifGeo({ model, view, pos, memo }) {
  const I = ifIndex(model), ids = ifShown(I, view), lines = ifLines(I, view, new Set(ids)), P = id => (IF_OBJ(pos) && Object.hasOwn(pos, id) ? pos[id] : [0, 0]);
  const nodes = ids.map(id => { const n = I.at.get(id), st = ifStereo(n), pr = IF_OBJ(n.props) ? n.props : {};
    const look = n.type === 'uml.Comment' ? { shape: 'note' } : n.type === 'uml.Actor' ? { shape: 'actor', stereotypes: st } : n.type === 'uml.Component' ? { shape: 'component', stereotypes: st, keyword: !!pr.keyword }
      : n.type === 'uml.InformationItem' ? { shape: 'information-item', stereotypes: st, compartments: [] } : { shape: 'if-classifier', stereotypes: [...[ifKey(n.type || 'uml.Class')].filter(Boolean), ...st], compartments: [] };
    const d = { id, label: ifName(n), type: n.type || 'uml.Class', kind: 'file', ...look, aria: ifNodeName(I, n), col: P(id)[0], row: P(id)[1] };
    return { ...d, ...SHAPE[d.shape].size(d) }; });
  const edges = lines.map(e => { const flow = e.type === 'uml.InformationFlow', label = flow ? '«flow» ' + ifSays(I, e) : e.label;
    return { id: e.id, _id: e.id, type: e.type, from: e.from, to: e.to, label: IF_HAS(label) ? label : undefined, end: flow ? { from: 'none', to: 'open', dashed: true } : { from: 'none', to: 'none', dashed: true },
      aria: ifLineName(I, e), cut: 280, ...(P(e.from)[0] - P(e.to)[0] > 1 ? { fromSide: 'bottom', toSide: 'bottom' } : {}), ...(IF_OBJ(e.style) || typeof e.style === 'string' ? { style: e.style } : {}) }; });
  const g = layoutTyped({ nodes, edges, direction: view.direction === 'down' ? 'down' : 'right', gap: 48, rgap: 56, labelGaps: true, repair: false, reroute: false }, memo);
  return { ...g, legend: ifLegend(g.edges), order: [...ids, ...lines.map(e => e.id)] }; // a new object: what layoutTyped returned is never edited (§2.6)
}

/* ---- validators (§7.4). Each problem: { level, rule, path, message, ids } ---- */
const IF_RULES = {
  'conveyed-some': 'an information flow conveys one element at least',
  'conveyed-kind': 'each element a flow conveys is an information item, a class, an interface, a component or a signal of the model',
  'conveyed-once': 'a flow conveys each element once (UML: conveyed is a set)',
  'flow-ends': 'an information flow joins two classes, interfaces, components or actors, never an information item or a comment',
};
function ifProblems(model) {
  const out = [], I = ifIndex(model), say = (rule, path, ids, msg) => out.push({ level: 'error', rule, path, ids: ids.filter(x => x != null), message: `${rule}: ${msg}` });
  const q = id => JSON.stringify(I.nm(id)), kind = id => (I.at.has(id) ? ifWord(I.at.get(id).type).toLowerCase() : 'nothing');
  IF_ARR(model && model.edges).forEach((e, i) => { if (!IF_OBJ(e) || e.type !== 'uml.InformationFlow') return; const path = `edges[${i}]`, c = I.conveyed(e);
    if (!c.length) say('conveyed-some', path, [e.id], `${e.id} conveys nothing: a flow conveys one element at least`);
    c.forEach((id, j) => { if (c.indexOf(id) < j) say('conveyed-once', `${path}.props.conveyed[${j}]`, [e.id, typeof id === 'string' ? id : null], `${e.id} conveys ${q(id)} twice: a flow conveys each element once`);
      else if (!I.at.has(id) || !IF_CONVEY.includes(I.at.get(id).type))
      say('conveyed-kind', `${path}.props.conveyed[${j}]`, [e.id, typeof id === 'string' ? id : null], I.at.has(id) ? `${e.id} conveys ${q(id)}, a ${kind(id)}: it conveys information items, classes, interfaces, components and signals` : `${e.id} conveys ${JSON.stringify(id)}, which the model does not hold`); });
    if (!IF_ENDS.includes((I.at.get(e.from) || {}).type) || !IF_ENDS.includes((I.at.get(e.to) || {}).type))
      say('flow-ends', path, [e.id, e.from, e.to], `${e.id} runs from ${q(e.from)} (${kind(e.from)}) to ${q(e.to)} (${kind(e.to)}): a flow joins two classes, interfaces, components or actors`); });
  return out;
}

/* ---- describe(): the view in sentences, each element by its accessible name in the view's order, then each line ---- */
function ifDescribe(model, viewId) {
  const v = IF_ARR(model && model.views).find(x => IF_OBJ(x) && x.id === viewId); if (!v) throw new Error(`umlimator: no view ${JSON.stringify(viewId)}`);
  const I = ifIndex(model), ids = ifShown(I, v), lines = ifLines(I, v, new Set(ids));
  return [`${v.title || v.id}: an information flow diagram of ${ifPlural(ids.length, 'element')} and ${ifPlural(lines.length, 'line')}.`,
    ...ids.map(id => ifNodeName(I, I.at.get(id)) + '.'), ...lines.map(e => ifLineName(I, e) + '.')].join('\n');
}

/* ---- editing (§7.4) ---- */
// the elements a flow may convey, information items first, then classifiers, each in the model's order
const ifConveyable = I => [...I.at.values()].filter(n => IF_CONVEY.includes(n.type)).sort((a, b) => (b.type === 'uml.InformationItem') - (a.type === 'uml.InformationItem'));
// connect: a flow between two classifiers or actors asks which element it conveys; other ends are refused, said on the hint line
function ifConnect(model, view, from, to, at, line) {
  if (!IF_OBJ(line) || line.type !== 'uml.InformationFlow') return null;
  const I = ifIndex(model);
  if (![from, to].every(id => IF_ENDS.includes((I.at.get(id) || {}).type))) return { error: 'An information flow joins two classes, interfaces, components or actors' };
  const can = ifConveyable(I); if (!can.length) return { error: 'Add an information item for the flow to convey first' };
  const used = new Set(); JSON.stringify(model, (k, v) => { if (k === 'id' && typeof v === 'string') used.add(v); return v; });
  let k = 1; while (used.has('flow' + k)) k++;
  return { pick: can.map(ifName), then: i => [{ op: 'add', element: { id: 'flow' + k, type: 'uml.InformationFlow', from, to, props: { conveyed: [can[i].id] } }, view: view.id }] };
}
// rename (F2, a double-click on a selected flow): the flow's text as drawn, `[name:] element, element`, «flow» left out or not;
// each element by its name (an information item first), else by its id; a name may hold `:` or `,` (`Billing::Receipt`). The
// text is read with no name first, then named at each `:` in turn; the reading that keeps the flow as it is wins, else the first
// that names elements throughout. Sets conveyed (each once) and the name, each when it changed
function ifRename(model, view, id, text) {
  const I = ifIndex(model), e = I.E.find(x => x.id === id); if (!e || e.type !== 'uml.InformationFlow') return null;
  const t = String(text ?? '').replace(/^\s*«flow»\s*/, ''), can = ifConveyable(I), find = s => can.find(n => ifName(n) === s) || can.find(n => n.id === s);
  // a list read entry by entry, each the longest run of comma-separated parts that names an element
  const list = s => { const p = s.split(','), ids = []; let i = 0;
    while (i < p.length) { if (!p[i].trim()) { i++; continue; }
      let j = p.length, x; while (j > i && !(x = find(p.slice(i, j).join(',').trim()))) j--;
      if (!x) return { error: `No information item or classifier is named ${p[i].trim()}` }; ids.push(x.id); i = j; }
    return ids.length ? { ids: [...new Set(ids)] } : { error: 'A flow conveys one element at least' }; };
  const reads = [-1, ...[...t].flatMap((ch, k) => (ch === ':' ? [k] : []))].map(k => ({ name: k < 0 ? '' : t.slice(0, k).trim(), ...list(k < 0 ? t : t.slice(k + 1)) }));
  const same = r => r.ids && r.name === (e.label ?? '') && JSON.stringify(r.ids) === JSON.stringify(I.conveyed(e));
  const r = reads.find(same) || reads.find(x => x.ids); if (!r) return { error: reads[reads.length > 1 ? 1 : 0].error };
  return [...(JSON.stringify(r.ids) !== JSON.stringify(I.conveyed(e)) ? [{ op: 'set', id, path: 'props.conveyed', value: r.ids }] : []),
    ...(r.name !== (e.label ?? '') ? [{ op: 'set', id, path: 'label', value: r.name || undefined }] : [])];
}

// remove: Shift + Delete on what flows convey takes every flow left conveying nothing (conveyed-some), in the same
// transaction, said on the hint line; a flow conveying something else keeps it (apply() drops the id: refs). Else the default
function ifRemove(model, view, ids, fromModel) {
  const I = ifIndex(model), gone = new Set(IF_ARR(ids)), flows = fromModel ? I.E.filter(e => e.type === 'uml.InformationFlow' && ![e.id, e.from, e.to].some(x => gone.has(x))
    && I.conveyed(e).length && I.conveyed(e).every(x => gone.has(x))) : [];
  if (!flows.length) return null;
  return { commands: [...gone, ...flows.map(e => e.id)].map(id => ({ op: 'delete', id })),
    say: `Deleted ${[...gone].map(id => { const l = I.E.find(e => e.id === id); return l ? `the line ${I.nm(l.from)} → ${I.nm(l.to)}` : JSON.stringify(I.nm(id)); }).join(', ')} and the ${ifPlural(flows.length, 'flow')} that conveyed nothing else: ${flows.map(e => `${I.nm(e.from)} → ${I.nm(e.to)}`).join(', ')}` };
}

const IF_STEREO = { key: 'stereotypes', label: 'Stereotypes', kind: 'list' };
const IF_TYPE = registerDiagramType('uml.information-flow', {
  title: 'information flow diagram',
  elements: [['Class', 'Class'], ['Interface', 'Interface'], ['Component', 'Component'], ['Actor', 'Actor'], ['InformationItem', 'Information item'], ['Comment', 'Comment']].map(([t, label]) => ({ type: 'uml.' + t, label })),
  lines: [['InformationFlow', 'Information flow'], ['CommentLink', 'Comment link']].map(([t, label]) => ({ type: 'uml.' + t, label })),
  props: { 'uml.Class': [IF_STEREO], 'uml.Interface': [IF_STEREO], 'uml.Component': [IF_STEREO], 'uml.Actor': [IF_STEREO], 'uml.InformationItem': [], 'uml.InformationFlow': [], 'uml.CommentLink': [] },
  refs: { 'uml.InformationFlow': { 'props.conveyed': 'drop' } }, // a deleted element leaves every flow that conveys it
  layout: ifGeo,
  validate: ifProblems,
  rules: IF_RULES,
  describe: ifDescribe,
  edits: { connect: ifConnect, rename: ifRename, remove: ifRemove },
  // the PDF (§9): an element's kind; an information item's rows, and any conveyed element's, the flows that convey it; a flow's text, what it conveys
  word: (model, id) => { const x = ifIndex(model).at.get(id); return x && Object.hasOwn(IF_WORD, x.type) ? IF_WORD[x.type] : null; },
  rows: (model, view, id) => { const I = ifIndex(model), x = I.at.get(id); return x && (x.type === 'uml.InformationItem' || I.flowsOf(id).length) ? I.flowsOf(id).map(e => `${I.nm(e.from)} → ${I.nm(e.to)}`) : null; },
  text: (model, view, id) => { const I = ifIndex(model), e = I.E.find(x => x.id === id); return e && e.type === 'uml.InformationFlow' ? ifSays(I, e) : null; },
});
/* ---------- C4's elements and static views, c4.landscape, c4.context, c4.container, c4.component (work package M2.6,
   notes/milestone-2.md §5.1, §5.2, §6.1, §6.5, §7.5, §7.5.1) ----------
   People, software systems, containers and components, each drawn in the map's card shape its props.shape names (a person
   `person`, the rest `box`, by default: S11) with C4's three lines over it: its name, [Container: technology], its
   description; an external element grey. A view's subject, when it lists it, is a dashed boundary holding what it owns
   that the view shows (ownersOn). A relationship whose end the view does not show is drawn between the nearest owners it
   shows, one implied line a pair, dashed, unless a relationship joins them already (§5.2): derived when drawn, never stored,
   its id `<from>-><to>`. Each view kind checks what it may show (§5.1). D on a software system or a container that opens
   no view makes its container or component view (§6.1). One definition, registered under the four view names; the
   dynamic and deployment views are src/c4/views.js's, on the helpers exported here. Laid out by layoutTyped from the
   host's ranking, repair and reroute off (§11). Ships in lib/umlimator-all.js only. */

const C4_OBJ = x => x !== null && typeof x === 'object' && !Array.isArray(x), C4_ARR = x => (Array.isArray(x) ? x : []);
const C4_HAS = x => x != null && String(x).trim() !== '';
const C4_P = x => (C4_OBJ(x.props) ? x.props : {});
const c4Name = x => String(x.label ?? x.id);
const c4Plural = (k, w) => `${k} ${k === 1 ? w : w + 's'}`;
const C4_WORD = { 'c4.Person': 'Person', 'c4.SoftwareSystem': 'Software system', 'c4.Container': 'Container', 'c4.Component': 'Component',
  'c4.DeploymentNode': 'Deployment node', 'c4.ContainerInstance': 'Container instance', 'uml.Comment': 'Comment' };
const C4_TAG = { 'c4.Person': 'Person', 'c4.SoftwareSystem': 'Software System', 'c4.Container': 'Container', 'c4.Component': 'Component' };
const c4Word = x => (Object.hasOwn(C4_WORD, x.type) ? C4_WORD[x.type] : String(x.type ?? '').split('.').pop());
const C4_STATIC = ['c4.Person', 'c4.SoftwareSystem', 'c4.Container', 'c4.Component'], C4_DEPLOY = ['c4.DeploymentNode', 'c4.ContainerInstance'];
// the map's card shapes an element may name (S11): all but UML's node, which is the deployment view's
const C4_SHAPES = ['box', 'person', 'robot', 'browser', 'window', 'terminal', 'mobile', 'cylinder', 'pipe', 'folder', 'document', 'hexagon'];
const c4Shape = x => { const s = String(C4_P(x).shape ?? '').toLowerCase(); return C4_SHAPES.includes(s) ? s : x.type === 'c4.Person' ? 'person' : 'box'; };
const c4Ext = x => C4_P(x).external === true;
// "[Container: Python, FastAPI]", "[Software System]", "[Person]"
const c4TagOf = x => { const t = C4_TAG[x.type] || c4Word(x), tech = C4_P(x).technology; return `[${t}${C4_HAS(tech) && x.type !== 'c4.Person' && x.type !== 'c4.SoftwareSystem' ? ': ' + tech : ''}]`; };

/* ---- the element (§7.5): the map shape's outline, det and face, sized by its text ---- */
const C4 = { name: 13, nlh: 17, tag: 10, tlh: 14, d: 11, dlh: 14, dw: 220, dk: 4, minW: 160, maxW: 280, px: 14, py: 10, gap: 4 };
const C4_TOP = { person: 26, robot: 16, browser: 14, window: 14, terminal: 14, folder: 9 }, C4_SIDE = { mobile: 12, pipe: 12, hexagon: 12 };
function c4Parts(n) {
  const pad = C4.px + (C4_SIDE[n.sh] || 0), max = C4.maxW - 2 * pad, name = flowWrap(n.label, C4.name, max, 2), tag = fit(n.tag || '', C4.tag, max);
  const desc = C4_HAS(n.desc) ? flowWrap(n.desc, C4.d, Math.min(C4.dw, max), C4.dk) : [];
  const w = Math.ceil(Math.min(C4.maxW, Math.max(C4.minW, Math.max(...name.map(t => textW(t, C4.name) * 1.05), textW(tag, C4.tag), ...desc.map(t => textW(t, C4.d))) + 2 * pad)));
  const text = Math.max(1, name.length) * C4.nlh + C4.tlh + (desc.length ? C4.gap + desc.length * C4.dlh : 0), body = text + 2 * C4.py;
  let h = (C4_TOP[n.sh] || 0) + body, top = C4_TOP[n.sh] || 0;
  if (n.sh === 'cylinder') { for (let k = 0; k < 4; k++) h = body + 3 * Math.max(5, Math.round(h * .11)); top = 2 * Math.max(5, Math.round(h * .11)); } // the lid above, its rim below
  return { name, tag, desc, w, h: Math.ceil(h), top, text, pad };
}
const c4Text = (x, y, t, px, wt, fill, cls, more = '') => `<text x="${r2(x)}" y="${r2(y)}" text-anchor="middle" class="${cls}"${more} fill="${fill}" style="font:${wt} ${px}px var(--um-sans)">${esc(t)}</text>`;
const C4_EL = {
  size: n => { const p = c4Parts(n); return { w: p.w, h: p.h }; },
  out: (n, d = 0) => SHAPE[n.sh || 'box'].out(n, d), face: n => SHAPE[n.sh || 'box'].face(n),
  inset: (n, s, t) => SHAPE[n.sh || 'box'].inset(n, s, t),
  // its outline, the map shape's details (a person's head, a cylinder's lid) and C4's three lines, centred under its top
  draw(n, c, f) {
    const S = SHAPE[n.sh || 'box'], P = c4Parts(n), cx = n.x + n.w / 2, max = n.w - 2 * P.pad, bottom = n.sh === 'cylinder' ? P.top / 2 : 0;
    let y = n.y + P.top + (n.h - P.top - bottom - P.text) / 2;
    const tx = [];
    P.name.forEach((t, i) => { tx.push(c4Text(cx, y + 13, fit(t, C4.name, max), C4.name, 600, 'var(--um-text)', 'c-name', i ? '' : ` data-o="${esc(n.id)}"`)); y += C4.nlh; });
    tx.push(c4Text(cx, y + 10, fit(P.tag, C4.tag, max), C4.tag, 400, 'var(--um-muted)', 'c-st')); y += C4.tlh + C4.gap;
    P.desc.forEach(t => { tx.push(c4Text(cx, y + 11, fit(t, C4.d, max), C4.d, 400, 'var(--um-text)', 'c-desc')); y += C4.dlh; });
    return `<g class="node c4${n.ext ? ' c4-ext' : ''}" data-id="${esc(n.id)}" data-shape="c4" data-c4="${n.sh}" tabindex="-1" role="img" aria-label="${esc(n.aria || `${c4Word(n)} ${n.label ?? ''}`)}">`
      + `<path d="${S.out(n)}" class="n-mask"/><path d="${S.out(n)}" class="n-body" fill="${f}" stroke="${c}"/>${S.det ? S.det(n, c, n.k) : ''}<g class="c-head">${tx.join('')}</g></g>`;
  },
};
C4_EL.ports = (n, side, k = 1) => portsOn(C4_EL, n, side, k);
SHAPE.c4 = C4_EL;
// a boundary (§7.5.1): a dashed box titled "<name> [Software System]", as C4 draws it
SHAPE['c4-boundary'] = { frame: f => `<rect class="family-box" x="${f.x}" y="${f.y}" width="${f.w}" height="${f.h}" rx="6" fill="none" stroke="var(--um-muted)" stroke-dasharray="6 4"/>`
  + `<text class="family-title" x="${r2(f.x + 12)}" y="${r2(f.y + 18)}" fill="var(--um-text)" style="font:600 12px var(--um-sans)" data-t="ft" data-o="${esc(f.id)}">${esc(fit(f.title ?? f.label ?? f.id, 12, f.w - 24))}</text>` };

/* ---- the model read: elements by id, their owners, relationships ---- */
function c4Index(model) {
  const at = new Map(); C4_ARR(model && model.nodes).forEach(n => { if (C4_OBJ(n) && typeof n.id === 'string' && !at.has(n.id)) at.set(n.id, n); });
  const E = C4_ARR(model && model.edges).filter(e => C4_OBJ(e) && typeof e.id === 'string'), rels = E.filter(e => e.type === 'c4.Relationship');
  // the chain of owners, nearest first; a cycle (the core's error) stops it
  const chain = id => { const out = [], seen = new Set([id]); for (let p = (at.get(id) || {}).parent; p != null && at.has(p) && !seen.has(p); p = at.get(p).parent) { seen.add(p); out.push(p); } return out; };
  const kids = (id, type) => [...at.values()].filter(n => n.parent === id && n.type === type).map(n => n.id);
  return { at, E, rels, chain, kids };
}
const C4_LOOK = { boxTypes: ['c4.SoftwareSystem', 'c4.Container'], qualify: false, shape: () => 'c4-boundary', word: c4Word };
// the view's picture: its boxes, titled as C4 titles a boundary, each named by what it holds
function c4Pic(model, view) {
  const pic = ownersOn(model, view, C4_LOOK), I = c4Index(model);
  const boxes = pic.boxes.map(b => { const x = pic.at.get(b.id), held = pic.holds(b.id).map(id => pic.at.get(id)), k = new Map();
    held.forEach(y => { const w = c4Word(y).toLowerCase(); k.set(w, (k.get(w) || 0) + 1); });
    return { ...b, title: `${c4Name(x)} [${C4_TAG[x.type]}]`, aria: `${c4Word(x)} ${c4Name(x)}, a boundary holding ${[...k].map(([w, c]) => c4Plural(c, w)).join(', ') || 'nothing'}` }; });
  return { ...pic, I, boxes };
}

/* ---- the lines drawn (§5.2): the view's own relationships between shown elements, then one implied line a pair ---- */
// a relationship's end lifted to what the view shows of it: itself, else its nearest shown owner; null when the first shown
// thing up its chain is a boundary (a boundary is no end) or nothing is shown
function c4Lift(pic, id) {
  for (const x of [id, ...pic.I.chain(id)]) if (pic.ids.includes(x)) return pic.open.has(x) ? null : x;
  return null;
}
